-- Mike Chen (10) now reports to Andrew Adams (1)
UPDATE "Employee" SET "ReportsTo" = 1 WHERE "EmployeeId" = 10;
"}

{"query": "
-- Robert's manager
SELECT "ReportsTo" AS roberts_manager FROM "Employee" WHERE "EmployeeId" = 7;
"}

{"query": "
-- Employees who report to Robert
SELECT "EmployeeId", "FirstName", "LastName" FROM "Employee" WHERE "ReportsTo" = 7;
"}

{"query": "
-- Customers assigned to Robert
