"}

{"name": "promote_laura_callahan_add_salary", "query": "
-- Add salary column to Employee table
ALTER TABLE "Employee" ADD COLUMN "salary" DECIMAL;

-- Promote Laura Callahan (EmployeeId = 8) to Senior IT Specialist
UPDATE "Employee" SET "Title" = 'Senior IT Specialist' WHERE "EmployeeId" = 8;

-- Set Laura's salary to 75000.00
UPDATE "Employee" SET "salary" = 75000.00 WHERE "EmployeeId" = 8;

-- Set all other employees' salary to 50000.00
UPDATE "Employee" SET "salary" = 50000.00 WHERE "EmployeeId" != 8;
"}

{"query": "
-- Full Employee roster final state
SELECT "EmployeeId", "FirstName", "LastName", "Title", "ReportsTo", "salary"
FROM "Employee"
ORDER BY "EmployeeId";
"}
